const pairs = items.map(i => i.json);
const supabaseUrl = 'https://fliqklclucdhjemdjatr.supabase.co';
const anonKey = 'REPLACE_WITH_ANON_KEY';

let hits = 0;
const details = [];

for (const pair of pairs) {
  try {
    const resp = await fetch(supabaseUrl + '/rest/v1/rpc/search_ads', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'apikey': anonKey, 'Authorization': 'Bearer ' + anonKey },
      body: JSON.stringify({ query_text: pair.query_text, result_limit: 10 })
    });
    const rows = await resp.json();
    const found = Array.isArray(rows) && rows.some(r => Number(r.id) === Number(pair.expected_ad_id));
    if (found) hits++;
    details.push({ query: pair.query_text.slice(0,40), expected: pair.expected_ad_id, found });
  } catch(e) {
    details.push({ query: pair.query_text.slice(0,40), expected: pair.expected_ad_id, found: false, error: e.message });
  }
}

const recall = hits / pairs.length;
return [{ json: { recall_at_10: recall, hits, total: pairs.length, week: new Date().toISOString().split('T')[0], details } }];
